// Serves the social-share image (/og-image.png) from embedded data, because the GitHub web editor can't take binary files.
const B64 = "";
let bytes;
export function onRequestGet() {
  if (!bytes) { const s = atob(B64); bytes = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) bytes[i] = s.charCodeAt(i); }
  return new Response(bytes, { headers: { "content-type": "image/png", "cache-control": "public, max-age=86400", "content-length": String(bytes.length) } });
}
